class CustomError : public std::runtime_error {
public:
    CustomError() : runtime_error("Error occurred") {}
};

void run_operation(int val) {
    if (val == 0) {
        throw CustomError();
    }
}

try {
    run_operation(0);
} catch (const CustomError& e) {
    // Specific handling
} catch (const std::exception& e) {
    // Generic handling
    e.what();
}

// Rethrowing an exception
try {
    throw std::runtime_error("Initial");
} catch (const std::exception&) {
    throw; // Re-throws the current exception
}
